%% |dependency cycles are rejected| — laws/decomposition.lawspec:274
%% A ring of two or more sub-questions, each depending on the next, cannot
%%     be resolved and is rejected.
%% for all (size :: BigUInt) => match (attempt (decompose "q" (ringOf size))) { Either::Left lawspecFailure -> let it = lawspecFailure in match (it) { cake.laws.decomposition::type::Rejection::InvalidDecomposition _lawspecSelection0x0 -> true }; Either::Right lawspecResult -> false } = true end for all
law_dependency_cycles_are_rejected(Schema, Symbols, [Size]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_beam_effects:attempt(
                <<"lawspec::ability::Fail(cake.laws.decomposition::type::Rejection)">>,
                fun() ->
                    lawspec_definitions:decompose(
                        Schema,
                        Symbols,
                        <<"q">>,
                        lawspec_definitions:ring_of(Schema, Symbols, Size)
                    )
                end,
                fun(_FailureValue) ->
                    lawspec_beam_schema:construct(
                        <<"Either::Right">>,
                        [_FailureValue],
                        {
                            <<"Either">>,
                            [
                                {<<"cake.laws.decomposition::type::Rejection">>, []},
                                {<<"cake.laws.decomposition::type::Decomposition">>, []}
                            ]
                        },
                        Schema
                    )
                end,
                fun(_FailureValue) ->
                    lawspec_beam_schema:construct(
                        <<"Either::Left">>,
                        [_FailureValue],
                        {
                            <<"Either">>,
                            [
                                {<<"cake.laws.decomposition::type::Rejection">>, []},
                                {<<"cake.laws.decomposition::type::Decomposition">>, []}
                            ]
                        },
                        Schema
                    )
                end
            ),
            #{
                <<"Either::Left">> => fun([Failure]) ->
                    lawspec_beam_runtime:bind(
                        Failure,
                        fun(It) ->
                            lawspec_beam_schema:match(
                                It,
                                #{
                                    <<"cake.laws.decomposition::type::Rejection::InvalidDecomposition">> => fun(
                                        [_Selection]
                                    ) ->
                                        true
                                    end
                                }
                            )
                        end
                    )
                end,
                <<"Either::Right">> => fun([_Result_2]) -> false end
            }
        ),
        true,
        ?LAW_DEPENDENCY_CYCLES_ARE_REJECTED
    ).

