-define(LAW_FLAT_DECOMPOSITIONS_RESOLVE_IN_POSITIONAL_ORDER,
    <<"cake.laws.decomposition::|flat decompositions resolve in positional order|">>
).

%% |flat decompositions resolve in positional order| — laws/decomposition.lawspec:389
%% With no dependencies, sub-questions resolve in the order they were given;
%%     an atomic decomposition resolves nothing.
%% for all (questions :: List (Text)) => resolutionOrder "q" (plainEntries questions) = Range(0, Length(questions)) end for all
law_flat_decompositions_resolve_in_positional_order(Schema, Symbols, [Questions]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:resolution_order(
            Schema,
            Symbols,
            <<"q">>,
            lawspec_definitions:plain_entries(Schema, Symbols, Questions)
        ),
        lawspec_beam_runtime:helper(
            <<"range">>,
            [0, lawspec_beam_runtime:helper(<<"length">>, [Questions], [<<"List Text">>], 64)],
            [<<"Integer">>, <<"Integer">>],
            64
        ),
        ?LAW_FLAT_DECOMPOSITIONS_RESOLVE_IN_POSITIONAL_ORDER
    ).

law_flat_decompositions_resolve_in_positional_order_plan() ->
    [
        {
            fixed,
            [
                {
                    "|flat decompositions resolve in positional order| example |atomic|",
                    fun law_flat_decompositions_resolve_in_positional_order__atomic/0
                },
                {
                    "|flat decompositions resolve in positional order| example |three in a row|",
                    fun law_flat_decompositions_resolve_in_positional_order__three_in_a_row/0
                }
            ]
        },
        {
            finite,
            {
                branches,
                [
                    {
                        {
                            values,
                            [
                                fun(Symbols) -> finite_literal_1(Symbols) end,
                                fun(Symbols) -> finite_literal_2(Symbols) end,
                                fun(Symbols) -> finite_literal_3(Symbols) end,
                                fun(Symbols) -> finite_literal_4(Symbols) end,
                                fun(Symbols) -> finite_literal_5(Symbols) end,
                                fun(Symbols) -> finite_literal_6(Symbols) end,
                                fun(Symbols) -> finite_literal_7(Symbols) end,
                                fun(Symbols) -> finite_literal_8(Symbols) end,
                                fun(Symbols) -> finite_literal_9(Symbols) end,
                                fun(Symbols) -> finite_literal_10(Symbols) end,
                                fun(Symbols) -> finite_literal_11(Symbols) end,
                                fun(Symbols) -> finite_literal_12(Symbols) end,
                                fun(Symbols) -> finite_literal_13(Symbols) end,
                                fun(Symbols) -> finite_literal_14(Symbols) end,
                                fun(Symbols) -> finite_literal_15(Symbols) end,
                                fun(Symbols) -> finite_literal_4(Symbols) end,
                                fun(Symbols) -> finite_literal_5(Symbols) end,
                                fun(Symbols) -> finite_literal_16(Symbols) end,
                                fun(Symbols) -> finite_literal_17(Symbols) end
                            ]
                        },
                        {copies, 1}
                    }
                ]
            },
            fun(CaseIndex, CaseFactories) ->
                {
                    lawspec_beam_finite:description(
                        <<"|flat decompositions resolve in positional order|">>,
                        CaseIndex
                    ),
                    fun() ->
                        {Schema, Symbols} = lawspec_data:context(),
                        lawspec_beam_runtime:require(
                            law_flat_decompositions_resolve_in_positional_order(
                                Schema,
                                Symbols,
                                lawspec_beam_finite:values(Symbols, CaseFactories)
                            ),
                            ?LAW_FLAT_DECOMPOSITIONS_RESOLVE_IN_POSITIONAL_ORDER
                        )
                    end
                }
            end
        },
        {
            fixed,
            [
                {
                    "|flat decompositions resolve in positional order| property",
                    fun law_flat_decompositions_resolve_in_positional_order__property/0
                }
            ]
        }
    ].

law_flat_decompositions_resolve_in_positional_order_test_() ->
    lawspec_beam_finite:plan_cases(law_flat_decompositions_resolve_in_positional_order_plan()).

law_flat_decompositions_resolve_in_positional_order_case_at(Index) ->
    lawspec_beam_finite:case_at(law_flat_decompositions_resolve_in_positional_order_plan(), Index).

%% |flat decompositions resolve in positional order| example |atomic| — laws/decomposition.lawspec:402
law_flat_decompositions_resolve_in_positional_order__atomic() ->
    {Schema, Symbols} = lawspec_data:context(),
